--[[
    SN_Load.lua  (image embedded)
    ------------------------------------------------------------
    1) 載入原 AXkiV2 混淆腳本
    2) 所有標題 → "SN"
    3) 主視窗插入背景圖片層（背景之上、文字之下）
    ------------------------------------------------------------
    圖片已內嵌為 base64，執行時透過 writefile + getexecutorasset
    還原成 rbxassetid://，不需要另外傳圖。
    支援的執行器：Synapse / Krnl / Fluxus / Wave / Delta 等
    ------------------------------------------------------------
    把整個檔案上 GitHub raw，然後用：
       loadstring(game:HttpGet("你的_raw_網址"))()
    或直接整段貼進執行器。
--]]

