-- ===== 還原圖片為 rbxassetid =====
local function b64decode(s)
    local b='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    local lookup = {}
    for i = 1, #b do lookup[b:byte(i)] = i - 1 end
    -- 處理 padding 與換行
    s = s:gsub("[^A-Za-z0-9+/=]", "")
    local out = {}
    local idx = 1
    for i = 1, #s, 4 do
        local c1 = lookup[s:byte(i)] or 0
        local c2 = lookup[s:byte(i+1)] or 0
        local c3 = lookup[s:byte(i+2)] or 0
        local c4 = lookup[s:byte(i+3)] or 0
        local n = c1 * 262144 + c2 * 4096 + c3 * 64 + c4
        local b1 = math.floor(n / 65536) % 256
        local b2 = math.floor(n / 256) % 256
        local b3 = n % 256
        out[idx] = string.char(b1); idx = idx + 1
        if s:sub(i+2, i+2) ~= "=" then
            out[idx] = string.char(b2); idx = idx + 1
        end
        if s:sub(i+3, i+3) ~= "=" then
            out[idx] = string.char(b3); idx = idx + 1
        end
    end
    return table.concat(out)
end

local IMG = "rbxassetid://0"        -- 面板背景（fallback）
local BANNER_IMG = "rbxassetid://0" -- 頂部橫幅（fallback）

local function assetFromB64(b64, ext)
    local result = "rbxassetid://0"
    pcall(function()
        local bin = b64decode(b64)
        local path = "SN_" .. ext .. "_" .. tostring(math.random(100000, 999999)) .. "." .. ext
        if writefile then
            writefile(path, bin)
            if getexecutorasset then
                result = getexecutorasset(path)
            elseif getcustomasset then
                result = getcustomasset(path)
            end
        end
    end)
    return result
end

IMG = assetFromB64(IMG_B64, "jpg")
BANNER_IMG = assetFromB64(BANNER_B64, "png")
print("[SN_Loader] 面板背景：" .. IMG .. " | 橫幅圖：" .. BANNER_IMG)

-- ===== 1) 載入原腳本 =====
pcall(function()
    loadstring(game:HttpGet(
        "https://raw.githubusercontent.com/timmy109004/AXkiV2/refs/heads/main/ax%20script%20eee"
    ))()
end)

-- ===== 2) 找 UI =====
local CG = game:GetService("CoreGui")
local PG = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")
local vp = workspace.CurrentCamera.ViewportSize

-- 把圖片插進某 Frame（如果還沒插過）
local function insertImg(parent, asset)
    if not parent or not parent:IsA("GuiObject") then return end
    if parent:FindFirstChild("SN_BgImage") then
        parent.SN_BgImage.Image = asset
        return
    end
    local img = Instance.new("ImageLabel")
    img.Name = "SN_BgImage"
    img.Image = asset
    img.BackgroundTransparency = 1
    img.ScaleType = Enum.ScaleType.Crop
    img.Size = UDim2.new(1, 0, 1, 0)
    img.Position = UDim2.new(0, 0, 0, 0)
    local mz = math.huge
    for _, c in ipairs(parent:GetChildren()) do
        if c:IsA("GuiObject") and c.ZIndex < mz then mz = c.ZIndex end
    end
    if mz == math.huge then mz = 0 end
    img.ZIndex = mz + 1
    for _, c in ipairs(parent:GetChildren()) do
        if c ~= img and c:IsA("GuiObject") then
            c.ZIndex = math.max(c.ZIndex, mz + 2)
        end
    end
    img.Parent = parent
end

-- 判斷 Frame 是不是「頂部橫幅」：位置在螢幕上方、寬扁形狀
local function isTopBanner(f)
    if not f:IsA("Frame") then return false end
    local pos = f.AbsolutePosition
    local sz = f.AbsoluteSize
    return pos.Y < 180 and sz.X > 200 and sz.Y < 180 and sz.Y > 20
end

-- 把橫幅圖插到頂部橫幅 Frame
local function insertBanner(parent, asset)
    if not parent or not parent:IsA("GuiObject") then return end
    if parent:FindFirstChild("SN_Banner") then
        parent.SN_Banner.Image = asset
        return
    end
    local bimg = Instance.new("ImageLabel")
    bimg.Name = "SN_Banner"
    bimg.Image = asset
    bimg.BackgroundTransparency = 1
    bimg.ScaleType = Enum.ScaleType.Fit
    local arc = Instance.new("UIAspectRatioConstraint")
    arc.AspectRatio = 1000 / 384
    arc.Parent = bimg
    bimg.Size = UDim2.new(1, -20, 0.9, 0)
    bimg.Position = UDim2.new(0.5, 0, 0.5, 0)
    bimg.AnchorPoint = Vector2.new(0.5, 0.5)
    local maxZ = 0
    for _, c in ipairs(parent:GetChildren()) do
        if c:IsA("GuiObject") and c.ZIndex > maxZ then maxZ = c.ZIndex end
    end
    bimg.ZIndex = maxZ + 5
    bimg.Parent = parent
end

-- 處理一個 ScreenGui：標題改 SN + 插圖
local processed = {}
local bannerDone = {}
local function processGui(root)
    if not root then return end
    for _, o in ipairs(root:GetDescendants()) do
        -- 1) 文字 → SN
        if (o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox")) and o.Text and o.Text ~= "SN" and o.Text ~= "" then
            pcall(function() o.Text = "SN" end)
        end
        -- 2) 含文字的 Frame → 插圖
        if (o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox")) and o.Text and o.Text ~= "" then
            local p = o.Parent
            if p and p:IsA("Frame") then
                local sz = p.AbsoluteSize
                if sz.X < vp.X * 0.95 and sz.Y < vp.Y * 0.95 and sz.X > 60 and sz.Y > 30 then
                    if isTopBanner(p) then
                        if not bannerDone[p] then
                            bannerDone[p] = true
                            insertBanner(p, BANNER_IMG)
                        end
                    else
                        if not processed[p] then
                            processed[p] = true
                            insertImg(p, IMG)
                        end
                    end
                end
            end
        end
    end
end

-- ===== 3) 持續暴力掃描（每 0.3 秒一次，跑無限迴圈）=====
task.spawn(function()
    while true do
        pcall(function()
            for _, p in ipairs({CG, PG}) do
                for _, c in ipairs(p:GetChildren()) do
                    if c:IsA("ScreenGui") then
                        processGui(c)
                    end
                end
            end
        end)
        task.wait(0.3)
    end
end)

print("[SN_Loader] 啟動持續掃描器（每 0.3 秒）")
